import{_ as a,o as i,c as l,ae as r}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"TS7 and Release Channel Policy","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/14_TS7_AND_RELEASE_CHANNEL_POLICY.md","filePath":"sessions/20260226-helios-market-research/14_TS7_AND_RELEASE_CHANNEL_POLICY.md"}'),t={name:"sessions/20260226-helios-market-research/14_TS7_AND_RELEASE_CHANNEL_POLICY.md"};function s(n,e,o,c,d,p){return i(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="ts7-and-release-channel-policy" tabindex="-1">TS7 and Release Channel Policy <a class="header-anchor" href="#ts7-and-release-channel-policy" aria-label="Permalink to &quot;TS7 and Release Channel Policy&quot;">​</a></h1><p>Date: 2026-02-26 Status: Accepted</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Helios is <code>TS7-native</code> wherever possible.</p><ul><li>Prefer TypeScript 7 language features, type system features, and compiler/runtime tooling when stable in beta/RC channels.</li><li>No deliberate downleveling to older TS baselines unless a critical dependency hard-blocks adoption.</li></ul><h2 id="package-channel-policy" tabindex="-1">Package Channel Policy <a class="header-anchor" href="#package-channel-policy" aria-label="Permalink to &quot;Package Channel Policy&quot;">​</a></h2><p>Default package posture for Helios:</p><ul><li>prefer latest <code>beta</code> or <code>rc</code> releases</li><li>prefer latest prerelease Bun/ElectroBun-compatible packages</li><li>pin exact versions in lockfiles to ensure deterministic builds</li></ul><h2 id="constraints-and-guardrails" tabindex="-1">Constraints and Guardrails <a class="header-anchor" href="#constraints-and-guardrails" aria-label="Permalink to &quot;Constraints and Guardrails&quot;">​</a></h2><ol><li>Any prerelease adoption must include:</li></ol><ul><li>owner</li><li>rollback version</li><li>breakage blast radius</li></ul><ol start="2"><li>Required compatibility checks before upgrade merge:</li></ol><ul><li>runtime boot</li><li>renderer path boot (<code>ghostty</code> and <code>rio</code>)</li><li>protocol schema compatibility</li><li>lane/session lifecycle smoke path</li></ul><ol start="3"><li>Critical-path runtime packages are upgraded in canary waves:</li></ol><ul><li>Wave A: protocol and adapter layer</li><li>Wave B: renderer and terminal integration</li><li>Wave C: UI shell and secondary utilities</li></ul><h2 id="typescript-and-build-requirements" tabindex="-1">TypeScript and Build Requirements <a class="header-anchor" href="#typescript-and-build-requirements" aria-label="Permalink to &quot;TypeScript and Build Requirements&quot;">​</a></h2><ul><li>TS config should target TS7-native patterns first.</li><li>Avoid compatibility shims for old TS behavior.</li><li>Strict type mode remains enabled.</li><li>Runtime and UI packages share core type contracts from protocol schemas.</li></ul><h2 id="exceptions-process" tabindex="-1">Exceptions Process <a class="header-anchor" href="#exceptions-process" aria-label="Permalink to &quot;Exceptions Process&quot;">​</a></h2><p>If TS7-native or prerelease channel creates a hard blocker:</p><ol><li>document blocker with concrete package and version</li><li>apply temporary pin to nearest stable version</li><li>create explicit unpin task with due date</li></ol><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>TS7-native is used in runtime and desktop packages by default.</li><li>All major dependencies operate on latest beta/RC channels unless exception is documented.</li><li>Rollback paths are defined for every prerelease dependency in critical runtime paths.</li></ul>',22)])])}const m=a(t,[["render",s]]);export{h as __pageData,m as default};
